import{_ as n,o as t,c as i,a2 as a}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"Betrieb und Wartung","description":"","frontmatter":{"order":5,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/02.anleitungen/05.betrieb-und-wartung.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/anleitungen/betrieb-und-wartung.md","filePath":"de/adapter/sourceanalytix/anleitungen/betrieb-und-wartung.md","lastUpdated":null}'),r={name:"de/adapter/sourceanalytix/anleitungen/betrieb-und-wartung.md"};function s(l,e,d,o,h,u){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="betrieb-und-wartung" tabindex="-1">Betrieb und Wartung <a class="header-anchor" href="#betrieb-und-wartung" aria-label="Permalink to &quot;Betrieb und Wartung&quot;">​</a></h1><p><a id="update-sourceanalytix-downgrade"></a></p><h2 id="wie-aktualisiere-ich-sourceanalytix-und-was-ist-ein-downgrade" tabindex="-1">Wie aktualisiere ich SourceAnalytix (und was ist ein Downgrade)? <a class="header-anchor" href="#wie-aktualisiere-ich-sourceanalytix-und-was-ist-ein-downgrade" aria-label="Permalink to &quot;Wie aktualisiere ich SourceAnalytix (und was ist ein Downgrade)?&quot;">​</a></h2><p><strong>Kurz:</strong> SourceAnalytix wird derzeit nur über das Repository „latest&quot; (Beta) verteilt, nicht über „stable&quot;. Admin zeigt ein Update deshalb nur an, wenn in den ioBroker-Systemeinstellungen das Repository „latest&quot; aktiv ist. Dann aktualisierst du wie jeden anderen Adapter im Reiter „Adapter&quot;. Deine States und Einstellungen bleiben dabei erhalten.</p><p>Im Stable-Repository fehlt SourceAnalytix ganz (nachgeprüft am 13.11.2026). Das ist kein Fehler deiner Installation. Ins Stable-Repository kommt SourceAnalytix erst nach einer Testphase; danach bekommst du Updates auch mit „stable&quot;.</p><h3 id="so-aktualisierst-du" tabindex="-1">So aktualisierst du <a class="header-anchor" href="#so-aktualisierst-du" aria-label="Permalink to &quot;So aktualisierst du&quot;">​</a></h3><ol><li>Mach ein Backup deines ioBroker-Systems.</li><li>Öffne in Admin die Systemeinstellungen und wähle im Bereich „Repositories&quot; das Repository „latest&quot; (Beta) als aktives Repository.</li><li>Öffne den Reiter „Adapter&quot; und aktualisiere die Adapterliste.</li><li>Klicke bei SourceAnalytix auf den Update-Knopf.</li><li>Prüfe danach im Reiter „Instanzen&quot;, ob die Instanz läuft, und im Log, ob sie ohne Fehler gestartet ist.</li></ol><p>Über die Konsole geht es mit <code>iobroker upgrade sourceanalytix</code>. Auch das funktioniert nur mit einem Repository, in dem SourceAnalytix enthalten ist, also heute nur mit „latest&quot;. Eine bestimmte Version installierst du mit <code>iobroker upgrade sourceanalytix@0.6.1</code>. Die Versionsnummer steht dabei ohne „v&quot; davor.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Seit v0.6.0 braucht SourceAnalytix Node.js 22, js-controller 6.0.11 und Admin 7.8.23 oder neuer. Ab v0.7.0 ist Admin 8.0.0 oder neuer nötig, weil die Instanz-Einstellungen darauf aufbauen. Ist eine dieser Voraussetzungen älter, bietet ioBroker das Update nicht an oder die Installation bricht ab. Siehe <a href="./../erste-schritte/installation#requirements-sourceanalytix-have-node-js">Voraussetzungen</a>.</p></div><h3 id="was-beim-update-mit-deinen-daten-passiert" tabindex="-1">Was beim Update mit deinen Daten passiert <a class="header-anchor" href="#was-beim-update-mit-deinen-daten-passiert" aria-label="Permalink to &quot;Was beim Update mit deinen Daten passiert&quot;">​</a></h3><p>Alle Werte liegen als States und Objekte in ioBroker. Ein Update ändert daran nichts. Beim Update auf v0.6.0 oder neuer gilt außerdem:</p><ul><li>Die „Technische ID“, also der Ordnername unter <code>sourceanalytix.0</code>, bleibt gleich. SourceAnalytix trägt die bisherige ID als Output-ID in die Einstellungen des Datenpunkts ein.</li><li>Die bisher wirksame Rundung wird einmal pro Datenpunkt gespeichert. Ändern sich später die Vorgaben der Instanz, bleiben bestehende Datenpunkte bei ihrer Rundung.</li><li>Unter <code>sourceanalytix.0.priceDefinitions</code>, <code>priceHistory</code> und <code>basicPriceHistory</code> kommen neue States für Preise und Preisverlauf dazu.</li></ul><p><strong>Ab v0.7.0:</strong> Nach dem Update stehen alle bisherigen Quellen in den Instanz-Einstellungen im Tab „Übersicht&quot;, mit ihren bisherigen Einstellungen. Du musst nichts neu anlegen. Prüfe danach einmal den Tab „Probleme&quot;: Er zeigt zum Beispiel unpassende Startwerte oder einen verpassten Periodenwechsel mit einem Vorschlag zur Behebung (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1269" target="_blank" rel="noreferrer">#1269</a>).</p><h3 id="ich-sehe-kein-update" tabindex="-1">Ich sehe kein Update <a class="header-anchor" href="#ich-sehe-kein-update" aria-label="Permalink to &quot;Ich sehe kein Update&quot;">​</a></h3><ul><li><strong>Falsches Repository:</strong> Ist „stable&quot; aktiv, erscheint SourceAnalytix dort nicht mit einer neuen Version. Stell wie oben auf „latest&quot; um.</li><li><strong>Installation von GitHub:</strong> Hast du SourceAnalytix über das Katzen-Symbol direkt von GitHub installiert, zeigt Admin für diese Installation kein Update an. Installiere die gewünschte Version aus dem Repository „latest&quot; darüber, dann bekommst du wieder Updates.</li><li><strong>Voraussetzungen zu alt:</strong> Siehe Hinweis oben.</li></ul><h3 id="was-bedeuten-versionen-wie-0-4-8-alpha-3" tabindex="-1">Was bedeuten Versionen wie 0.4.8-alpha.3? <a class="header-anchor" href="#was-bedeuten-versionen-wie-0-4-8-alpha-3" aria-label="Permalink to &quot;Was bedeuten Versionen wie 0.4.8-alpha.3?&quot;">​</a></h3><p>Der Teil nach dem Bindestrich kennzeichnet eine Vorabversion zum Testen (<code>alpha</code>, <code>beta</code>). Die Version ohne Zusatz ist neuer als jede ihrer Vorabversionen: <code>0.4.8</code> ist neuer als <code>0.4.8-beta.0</code>. Installiere eine Vorabversion nur, wenn der Entwickler zum Testen aufruft, und mach vorher ein Backup.</p><h3 id="downgrade-auf-eine-altere-version-zuruck" tabindex="-1">Downgrade: auf eine ältere Version zurück <a class="header-anchor" href="#downgrade-auf-eine-altere-version-zuruck" aria-label="Permalink to &quot;Downgrade: auf eine ältere Version zurück&quot;">​</a></h3><p>Ein Downgrade installiert eine ältere Version über die vorhandene. Das brauchst du nur, wenn eine neue Version bei dir einen Fehler hat.</p><ol><li>Mach ein Backup.</li><li>Schalte im Reiter „Adapter&quot; den Expertenmodus ein.</li><li>Wähle bei SourceAnalytix „Bestimmte Version installieren&quot; und dort die gewünschte Version.</li><li>Alternativ über die Konsole, ebenfalls mit aktivem Repository „latest&quot;: <code>iobroker upgrade sourceanalytix@&lt;Version&gt;</code>, z. B. <code>iobroker upgrade sourceanalytix@0.6.1</code>.</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Eine ältere Version kennt Einstellungen nicht, die erst eine neuere eingeführt hat. Gehst du zum Beispiel unter v0.6.0 zurück, kennt SourceAnalytix keine selbst gewählten Output-IDs. Hast du eine geändert, schreibt die ältere Version die Werte wieder unter der alten ID. Spiel im Zweifel das Backup ein, statt nur die Version zu wechseln.</p></div><p><strong>Ab v0.6.2:</strong> Beim Update auf v0.6.2 bleiben alte Einträge <code>valueAtDeviceInit</code> in den Einstellungen der Datenpunkte stehen. SourceAnalytix liest sie nicht mehr; du musst nichts tun (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1263" target="_blank" rel="noreferrer">#1263</a>).</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/installation#install-sourceanalytix-create-instance">Installation und Instanz anlegen</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#after-update-restore-values-0">Nach Update oder Restore sind Werte 0</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#known-bugs-older-versions-please">Bekannte Fehler älterer Versionen</a> · <a href="#data-back-up-move-new">Wo liegen die Daten, wie sichere ich sie?</a></p><p><a id="disable-datapoint-remove-sources-states"></a></p><h2 id="wie-schalte-ich-einen-datenpunkt-ab-oder-entferne-quellen-und-states" tabindex="-1">Wie schalte ich einen Datenpunkt ab oder entferne Quellen und States? <a class="header-anchor" href="#wie-schalte-ich-einen-datenpunkt-ab-oder-entferne-quellen-und-states" aria-label="Permalink to &quot;Wie schalte ich einen Datenpunkt ab oder entferne Quellen und States?&quot;">​</a></h2><p><strong>Kurz:</strong> Ab v0.7.0 öffnest du in den Instanz-Einstellungen die Quelle und wählst bei „Aktionen“ eine von zwei Aktionen. „Deaktivieren“ hält SourceAnalytix für diese Quelle an, alle Werte bleiben erhalten und du kannst sie jederzeit wieder aktivieren. „Daten löschen“ entfernt den Ordner der Quelle mit allen Werten und Jahren und die SourceAnalytix-Einstellungen am Datenpunkt, endgültig.</p><h3 id="deaktivieren-oder-daten-loschen" tabindex="-1">Deaktivieren oder Daten löschen? <a class="header-anchor" href="#deaktivieren-oder-daten-loschen" aria-label="Permalink to &quot;Deaktivieren oder Daten löschen?&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>„Deaktivieren“</th><th>„Daten löschen“</th></tr></thead><tbody><tr><td>SourceAnalytix rechnet weiter</td><td>nein</td><td>nein</td></tr><tr><td>Ordner <code>sourceanalytix.0.&lt;Gerät&gt;</code> mit allen Jahren</td><td>bleibt</td><td>wird gelöscht</td></tr><tr><td>Einstellungen am Datenpunkt (Preis, Startwerte, Offset)</td><td>bleiben</td><td>werden gelöscht</td></tr><tr><td>Rückgängig machen</td><td>mit „Aktivieren“</td><td>nicht möglich</td></tr></tbody></table><h3 id="so-deaktivierst-du-eine-quelle-ab-v0-7-0" tabindex="-1">So deaktivierst du eine Quelle (ab v0.7.0) <a class="header-anchor" href="#so-deaktivierst-du-eine-quelle-ab-v0-7-0" aria-label="Permalink to &quot;So deaktivierst du eine Quelle (ab v0.7.0)&quot;">​</a></h3><ol><li>Öffne unter „Instanzen“ die Einstellungen der SourceAnalytix-Instanz und im Tab „Übersicht“ die Quelle.</li><li>Klicke bei „Aktionen“ in der Zeile „Deaktivieren“ auf den Knopf „Deaktivieren“. Das wirkt sofort, ohne Neustart.</li><li>In der Übersicht trägt die Quelle jetzt den Status „Deaktiviert“. Ihre States bleiben stehen, werden aber nicht mehr aktualisiert.</li></ol><p>Wieder einschalten kannst du die Quelle an derselben Stelle mit „Aktivieren“. SourceAnalytix rechnet dann mit den gespeicherten Einstellungen weiter.</p><h3 id="so-loschst-du-die-daten-einer-quelle-ab-v0-7-0" tabindex="-1">So löschst du die Daten einer Quelle (ab v0.7.0) <a class="header-anchor" href="#so-loschst-du-die-daten-einer-quelle-ab-v0-7-0" aria-label="Permalink to &quot;So löschst du die Daten einer Quelle (ab v0.7.0)&quot;">​</a></h3><ol><li>Öffne die Quelle wie oben und klicke bei „Daten löschen“ auf „Löschen“.</li><li>Der Dialog zeigt, was verschwindet: die Zahl der Datenpunkte im Ordner, das Archiv der Jahre, den Gesamtstand und die SourceAnalytix-Einstellungen am Datenpunkt.</li><li>Tippe zur Bestätigung den Namen der Quelle ein und klicke auf „Endgültig löschen“.</li></ol><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>„Daten löschen“ lässt sich nicht rückgängig machen. Gesamtstand, Startwerte und alle Jahre sind danach weg. Mach vorher ein Backup, wenn du die Werte vielleicht noch brauchst, und nimm „Deaktivieren“, wenn du nur pausieren willst.</p></div><p>Beide Aktionen brauchen eine laufende Instanz. Ist sie gestoppt, sind die Sofort-Aktionen gesperrt.</p><h3 id="viele-quellen-auf-einmal-abschalten" tabindex="-1">Viele Quellen auf einmal abschalten <a class="header-anchor" href="#viele-quellen-auf-einmal-abschalten" aria-label="Permalink to &quot;Viele Quellen auf einmal abschalten&quot;">​</a></h3><p>Hast du versehentlich viele Datenpunkte aktiviert, geht das Abschalten schneller über den Reiter „Objekte“: Markiere die Datenpunkte, öffne mit dem Schraubenschlüssel-Symbol ihre gemeinsamen Einstellungen und nimm bei <code>sourceanalytix.0</code> den Haken bei „aktiviert“ heraus. Die Ordner der Quellen bleiben dabei stehen. Löschen kannst du sie danach einzeln mit „Daten löschen“ oder im Reiter „Objekte“.</p><p><strong>Ab v0.7.0:</strong> Im Objekt-Dialog gibt es nur noch den Haken „aktiviert“. Andere Einstellungen, etwa Preisdefinition oder Schwelle, kannst du dort nicht mehr für mehrere Datenpunkte auf einmal ändern. Du stellst sie für jede Quelle in ihrer Detailansicht ein (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1286" target="_blank" rel="noreferrer">#1286</a>).</p><h3 id="datenpunkt-geloscht" tabindex="-1">Datenpunkt gelöscht <a class="header-anchor" href="#datenpunkt-geloscht" aria-label="Permalink to &quot;Datenpunkt gelöscht&quot;">​</a></h3><p>Löschst du den Quell-Datenpunkt selbst, zum Beispiel weil du ein Gerät entfernt hast, schaltet SourceAnalytix die Quelle von allein ab. Im Log steht „Source state … was deleted; SourceAnalytix disabled it while retaining calculated history“. Die berechneten Werte bleiben.</p><p><strong>Ab v0.7.0:</strong> Der Tab „Probleme“ meldet so eine Quelle als „Datenpunkt existiert nicht mehr“ und schlägt „Deaktivieren oder Daten löschen“ vor. Ein Ordner, zu dem es keinen Datenpunkt mehr gibt, erscheint in der Übersicht als „Ordner ohne Datenpunkt“ und lässt sich dort mit „Daten löschen“ entfernen. Die Daten auf einen neuen Datenpunkt zu übertragen, ist geplant (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1271" target="_blank" rel="noreferrer">#1271</a>).</p><h3 id="einzelne-perioden-entfernen" tabindex="-1">Einzelne Perioden entfernen <a class="header-anchor" href="#einzelne-perioden-entfernen" aria-label="Permalink to &quot;Einzelne Perioden entfernen&quot;">​</a></h3><p>Willst du nur bestimmte States nicht mehr, etwa die Quartale, schalte die Option in den Instanz-Einstellungen im Tab „Haupteinstellungen“ aus. SourceAnalytix löscht die passenden States beim nächsten Start. Von Hand gelöschte States legt es dagegen wieder an, solange Option und Quelle aktiv sind.</p><p><strong>Bis v0.6.x:</strong> Abschalten ging nur über den Haken „aktiviert“ in den SourceAnalytix-Einstellungen des Datenpunkts (Reiter „Objekte“, Schraubenschlüssel). Eine Aktion zum Löschen gab es nicht; den Ordner unter <code>sourceanalytix.0</code> hast du im Reiter „Objekte“ von Hand gelöscht, nachdem du die Quelle abgeschaltet hattest.</p><p><strong>Siehe auch:</strong> <a href="#restart-datapoint-clean-up-old">Wie fange ich mit einem Datenpunkt neu an?</a> · <a href="#data-back-up-move-new">Wo liegen die Daten?</a> · <a href="./../erste-schritte/erster-zaehler#configure-sourceanalytix-datapoint">Wo konfiguriere ich SourceAnalytix für einen Datenpunkt?</a></p><p><a id="data-back-up-move-new"></a></p><h2 id="wo-liegen-die-daten-wie-sichere-ich-sie-und-ziehe-ich-um" tabindex="-1">Wo liegen die Daten, wie sichere ich sie und ziehe ich um? <a class="header-anchor" href="#wo-liegen-die-daten-wie-sichere-ich-sie-und-ziehe-ich-um" aria-label="Permalink to &quot;Wo liegen die Daten, wie sichere ich sie und ziehe ich um?&quot;">​</a></h2><p><strong>Kurz:</strong> SourceAnalytix hat keine eigene Datenbank. Alle Werte liegen als normale Objekte und States in ioBroker, die Einstellungen jeder Quelle stehen im Objekt ihres Datenpunkts. Ein vollständiges ioBroker-Backup, zum Beispiel mit BackItUp, enthält deshalb alles. Für einen Umzug spielst du dieses Backup auf dem neuen System ein, aber nicht kurz vor Mitternacht.</p><h3 id="wo-was-liegt" tabindex="-1">Wo was liegt <a class="header-anchor" href="#wo-was-liegt" aria-label="Permalink to &quot;Wo was liegt&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Was</th><th>Wo</th></tr></thead><tbody><tr><td>Gesamtstand, laufende Perioden, Vorperioden, Jahresarchiv</td><td>Ordner <code>sourceanalytix.0.&lt;Gerät&gt;</code></td></tr><tr><td>Zuletzt verarbeitete Perioden und Kostenspeicher</td><td><code>periodMemory</code> und <code>dynamicCostMemory</code> im selben Ordner</td></tr><tr><td>Einstellungen der Quelle mit Startwerten und Offset</td><td>im Objekt des Quell-Datenpunkts unter <code>common.custom.sourceanalytix.0</code></td></tr><tr><td>Preisdefinitionen und Optionen der Instanz</td><td>in den Instanz-Einstellungen (Objekt <code>system.adapter.sourceanalytix.0</code>)</td></tr><tr><td>Preise und Preisverlauf</td><td><code>sourceanalytix.0.priceDefinitions</code>, <code>sourceanalytix.0.priceHistory</code> und <code>sourceanalytix.0.basicPriceHistory</code></td></tr><tr><td>Aufgezeichnete Verläufe</td><td>in deinem History-Adapter, nicht bei SourceAnalytix</td></tr></tbody></table><p>Die Technische ID findest du ab v0.7.0 in der Detailansicht der Quelle unter „Für Experten“.</p><h3 id="was-ins-backup-gehort" tabindex="-1">Was ins Backup gehört <a class="header-anchor" href="#was-ins-backup-gehort" aria-label="Permalink to &quot;Was ins Backup gehört&quot;">​</a></h3><p>Sichere immer das ganze ioBroker-System mit Objekten und States. Ein Backup nur des Ordners <code>sourceanalytix.0</code> reicht nicht, denn Startwerte und Offset stehen am Quell-Datenpunkt. Ohne sie passt der Gesamtstand nach einem Restore nicht mehr zum Zähler. Läuft ioBroker mit Redis, gehört auch die Redis-Sicherung dazu.</p><h3 id="so-ziehst-du-auf-neue-hardware-um" tabindex="-1">So ziehst du auf neue Hardware um <a class="header-anchor" href="#so-ziehst-du-auf-neue-hardware-um" aria-label="Permalink to &quot;So ziehst du auf neue Hardware um&quot;">​</a></h3><ol><li>Plane den Umzug nicht kurz vor Mitternacht, damit kein Periodenwechsel in die Zeit fällt, in der kein System läuft.</li><li>Mach auf dem alten System ein vollständiges Backup.</li><li>Installiere auf dem neuen System ioBroker und SourceAnalytix (siehe <a href="./../erste-schritte/installation#install-sourceanalytix-create-instance">Installation</a>) und spiel das Backup ein.</li><li>Starte die Instanz. Hat sie einen Tages-, Wochen- oder Monatswechsel verpasst, holt sie ihn beim Start für jede Quelle einmal nach.</li><li>Prüfe im Tab „Probleme“ der Instanz-Einstellungen, ob alles ohne Befund ist, und vergleiche den Gesamtstand mit deinem Zähler (ab v0.7.0).</li></ol><p>Weicht der Gesamtstand vom Zähler ab, gleichst du ihn mit der Aktion „Zählerstand angleichen“ an, siehe <a href="./zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Falsche Werte korrigieren</a>.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Ein Export nur des Objektbaums bringt die Struktur, aber keine Werte. Auch das Anlegen derselben Quellen auf dem neuen System ersetzt den Restore nicht: SourceAnalytix beginnt dann mit neuen Startwerten.</p></div><p>Bekommt der Quell-Datenpunkt auf dem neuen System eine andere ID, etwa weil du die Geräte mit einem anderen Adapter einbindest, ist das für SourceAnalytix eine neue Quelle mit einem neuen Ordner. Der alte Ordner bleibt als Archiv stehen. Die Daten auf einen neuen Datenpunkt zu übertragen, ist geplant (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1271" target="_blank" rel="noreferrer">#1271</a>).</p><p><strong>Ab v0.6.2:</strong> Den Verbrauch zwischen dem letzten Wert vor Mitternacht und dem ersten danach teilt SourceAnalytix nach der Zeit auf den alten und den neuen Tag auf (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1260" target="_blank" rel="noreferrer">#1260</a>). Fällt der Umzug doch über Mitternacht, landet so trotzdem nicht alles beim neuen Tag.</p><p><strong>Siehe auch:</strong> <a href="#iobroker-was-down-midnight-recover">ioBroker war um Mitternacht aus</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#after-update-restore-values-0">Nach Update oder Restore sind Werte 0</a> · <a href="#update-sourceanalytix-downgrade">Wie aktualisiere ich SourceAnalytix?</a></p><p><a id="restart-datapoint-clean-up-old"></a></p><h2 id="wie-fange-ich-mit-einem-datenpunkt-neu-an-und-raume-alte-jahre-auf" tabindex="-1">Wie fange ich mit einem Datenpunkt neu an und räume alte Jahre auf? <a class="header-anchor" href="#wie-fange-ich-mit-einem-datenpunkt-neu-an-und-raume-alte-jahre-auf" aria-label="Permalink to &quot;Wie fange ich mit einem Datenpunkt neu an und räume alte Jahre auf?&quot;">​</a></h2><p><strong>Kurz:</strong> Ab v0.7.0 löschst du die Daten der Quelle mit der Aktion „Daten löschen“ und legst sie mit „Quelle hinzufügen“ neu an. SourceAnalytix behandelt sie dann wie eine erste Aktivierung und beginnt alle Perioden bei 0. Ordner abgeschlossener Jahre kannst du unabhängig davon gefahrlos im Reiter „Objekte“ löschen.</p><p>Nur den Ordner der Quelle zu löschen reicht nicht für einen Neuanfang. Startwerte und Offset stehen in den Einstellungen am Datenpunkt, und solange die Quelle aktiv ist, legt SourceAnalytix den Ordner beim nächsten Start mit diesen Werten wieder an. „Daten löschen“ entfernt deshalb beides.</p><h3 id="so-fangst-du-neu-an-ab-v0-7-0" tabindex="-1">So fängst du neu an (ab v0.7.0) <a class="header-anchor" href="#so-fangst-du-neu-an-ab-v0-7-0" aria-label="Permalink to &quot;So fängst du neu an (ab v0.7.0)&quot;">​</a></h3><ol><li>Öffne unter „Instanzen“ die Einstellungen der SourceAnalytix-Instanz und im Tab „Übersicht“ die Quelle.</li><li>Wähle bei „Aktionen“ „Daten löschen“, tippe den Namen der Quelle ein und klicke auf „Endgültig löschen“. Ordner und Einstellungen am Datenpunkt sind danach weg.</li><li>Klicke im Tab „Übersicht“ auf „Quelle hinzufügen“ und wähle denselben Datenpunkt.</li><li>Wähle im Schritt „Startwerte“ „Ab jetzt zählen“. Alle Perioden beginnen dann bei 0.</li><li>Mit dem ersten Wert stehen im Log „Initiating … for the first time in SourceAnalytix“ und „Initialized empty period start values for … from current reading …“.</li></ol><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>Mit „Daten löschen“ ist auch der bisherige Gesamtstand weg. Willst du nur falsche Zahlen reparieren, nimm stattdessen „Zählerstand angleichen“, siehe <a href="./zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Falsche Werte korrigieren</a>. Mehr zu den beiden Aktionen „Deaktivieren“ und „Daten löschen“ steht unter <a href="#disable-datapoint-remove-sources-states">Datenpunkt abschalten oder entfernen</a>.</p></div><h3 id="alte-jahre-aufraumen" tabindex="-1">Alte Jahre aufräumen <a class="header-anchor" href="#alte-jahre-aufraumen" aria-label="Permalink to &quot;Alte Jahre aufräumen&quot;">​</a></h3><p>Jedes Jahr mit eingeschalteter „Jahresstatistik“ legt einen eigenen Ordner <code>sourceanalytix.0.&lt;Gerät&gt;.&lt;Jahr&gt;</code> an. Ordner abgeschlossener Jahre sind reine Historie und dürfen gelöscht werden.</p><ol><li>Öffne im Admin den Reiter „Objekte“ und dort <code>sourceanalytix.0.&lt;Gerät&gt;</code>.</li><li>Lösche den Ordner des Jahres, das du nicht mehr brauchst, zum Beispiel <code>2023</code>.</li><li>Lösche nicht <code>currentYear</code>, <code>cumulativeReading</code>, <code>periodMemory</code> und nicht den Ordner des laufenden Jahres. Diese States braucht SourceAnalytix weiter; solange die Quelle aktiv ist, legt es sie beim nächsten Start ohnehin neu an.</li></ol><p>Die Aktion „Kosten ab Datum neu rechnen“ rechnet nur Perioden, deren States es noch gibt. Gelöschte Jahre lässt sie aus.</p><p>Willst du künftig keine Wochen- oder Jahresordner mehr, schalte in den Instanz-Einstellungen im Tab „Haupteinstellungen“ unter „Jahresstatistik“ die Optionen „Wochen“, „Monate“ und „Quartale“ aus. SourceAnalytix löscht dann die States im Ordner des laufenden Jahres, ältere Jahre lässt es stehen.</p><p><strong>Bis v0.6.x:</strong> Eine Aktion zum Löschen gab es nicht. Für einen Neuanfang musstest du die Quelle abschalten, ihren Ordner im Reiter „Objekte“ löschen und außerdem die gespeicherten Startwerte und den Offset am Datenpunkt entfernen, sonst galt die neue Aktivierung nicht als erste. Ab v0.7.0 erledigt „Daten löschen“ das in einem Schritt.</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erster-zaehler#start-values-unit">Was trage ich bei den Startwerten ein?</a> · <a href="#data-back-up-move-new">Wo liegen die Daten?</a> · <a href="./werte-auswerten#evaluate-across-years-adjusting-everything">Über mehrere Jahre auswerten</a></p><p><a id="iobroker-was-down-midnight-recover"></a></p><h2 id="iobroker-war-um-mitternacht-aus-–-wie-hole-ich-den-tageswechsel-nach" tabindex="-1">ioBroker war um Mitternacht aus – wie hole ich den Tageswechsel nach? <a class="header-anchor" href="#iobroker-war-um-mitternacht-aus-–-wie-hole-ich-den-tageswechsel-nach" aria-label="Permalink to &quot;ioBroker war um Mitternacht aus – wie hole ich den Tageswechsel nach?&quot;">​</a></h2><p><strong>Kurz:</strong> Meist musst du nichts tun. SourceAnalytix merkt sich für jede Quelle, welchen Tag, welche Woche und welchen Monat es zuletzt abgeschlossen hat, und holt verpasste Wechsel beim nächsten Start selbst nach. Läuft die Instanz durch, prüft sie außerdem jede Stunde, ob ein Wechsel fehlt. Ab v0.7.0 kannst du den Wechsel in den Instanz-Einstellungen auch mit der Aktion „Perioden nachholen“ anstoßen.</p><h3 id="was-sourceanalytix-selbst-nachholt" tabindex="-1">Was SourceAnalytix selbst nachholt <a class="header-anchor" href="#was-sourceanalytix-selbst-nachholt" aria-label="Permalink to &quot;Was SourceAnalytix selbst nachholt&quot;">​</a></h3><ul><li><strong>Beim Start:</strong> Jede Quelle vergleicht beim Start den gespeicherten Stand im State <code>sourceanalytix.0.&lt;Gerät&gt;.periodMemory</code> mit dem heutigen Datum. Fehlt ein Tages-, Wochen-, Monats-, Quartals- oder Jahreswechsel, verarbeitet sie ihn einmal. Im Log steht dann „Processing calendar rollover for …“.</li><li><strong>Jede Stunde:</strong> Eine Sicherheitsprüfung holt einen Wechsel nach, den der Mitternachts-Zeitplan verpasst hat, obwohl die Instanz lief, etwa nach dem Ruhezustand des Rechners oder einer Korrektur der Systemzeit.</li></ul><p>Die Vorperioden wie <code>01_previousDay</code> bekommen auch beim Nachholen den Zeitstempel 23:59:59 Uhr des Vortags. Hat der Ausfall mehrere Tage gedauert, verarbeitet SourceAnalytix trotzdem nur einen Wechsel. <code>01_previousDay</code> enthält dann den Verbrauch des letzten Tages vor dem Ausfall, die Tage dazwischen bekommen keinen eigenen Wert.</p><h3 id="so-holst-du-den-wechsel-von-hand-nach-ab-v0-7-0" tabindex="-1">So holst du den Wechsel von Hand nach (ab v0.7.0) <a class="header-anchor" href="#so-holst-du-den-wechsel-von-hand-nach-ab-v0-7-0" aria-label="Permalink to &quot;So holst du den Wechsel von Hand nach (ab v0.7.0)&quot;">​</a></h3><ol><li>Öffne unter „Instanzen“ die Einstellungen der SourceAnalytix-Instanz. Fehlt ein Wechsel, meldet der Tab „Probleme“ „Periodenwechsel verpasst“ bei der betroffenen Quelle, mit dem Knopf „Nachholen“.</li><li>Alternativ öffnest du im Tab „Übersicht“ eine Quelle und klickst bei „Aktionen“ in der Zeile „Perioden nachholen“ auf „Nachholen“.</li><li>Danach erscheint „Periodenwechsel für &lt;Quelle&gt; nachgeholt“. Beide Wege gelten nur für diese eine Quelle, die anderen Quellen bleiben unberührt. Fehlt kein Wechsel, ändert sich nichts.</li></ol><h3 id="per-skript-oder-knopf-in-vis" tabindex="-1">Per Skript oder Knopf in VIS <a class="header-anchor" href="#per-skript-oder-knopf-in-vis" aria-label="Permalink to &quot;Per Skript oder Knopf in VIS&quot;">​</a></h3><p>Ohne Instanz-Einstellungen geht es über den State <code>sourceanalytix.0.info.recoverPeriods</code>: Schreibe <code>true</code> hinein (ohne Bestätigung, also <code>ack=false</code>). SourceAnalytix holt dann verpasste Wechsel <strong>aller</strong> Quellen nach und setzt den State danach auf <code>false</code> zurück. Aus einem Skript geht es mit <code>sendTo</code>, wahlweise für alle Quellen oder mit <code>source</code> nur für eine. Die Antwort nennt die Zahl der Quellen:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// alle Quellen</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sendTo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sourceanalytix.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;recoverPeriods&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {}, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`Wechsel nachgeholt für \${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">result</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">recovered</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">} Quellen\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// nur eine Quelle (ab v0.7.0), ID des Quell-Datenpunkts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sendTo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sourceanalytix.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;recoverPeriods&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {source: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;shelly.0.SHEM-3#1#.Total.ConsumedPower&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (result.error) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(result.message, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;warn&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>Ist die Quelle nicht aktiv, kommt <code>{error: &#39;sourceNotActive&#39;}</code> zurück.</p><p>Läuft gerade schon ein Wechsel, wird der Aufruf übersprungen und die Antwort ist 0.</p><h3 id="wohin-der-verbrauch-der-ausfallzeit-gebucht-wird" tabindex="-1">Wohin der Verbrauch der Ausfallzeit gebucht wird <a class="header-anchor" href="#wohin-der-verbrauch-der-ausfallzeit-gebucht-wird" aria-label="Permalink to &quot;Wohin der Verbrauch der Ausfallzeit gebucht wird&quot;">​</a></h3><p><strong>Ab v0.6.2:</strong> Den Verbrauch zwischen dem letzten Wert vor Mitternacht und dem ersten Wert danach teilt SourceAnalytix bei Zählerständen nach der Zeit auf: Der Anteil, der in den alten Tag fällt, kommt zu gestern, der Rest zum neuen Tag. Bis v0.6.1 landete alles beim neuen Tag (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1260" target="_blank" rel="noreferrer">#1260</a>).</p><p>Ein Beispiel: Der letzte Wert kommt um 22:00 Uhr, der nächste nach dem Neustart um 2:00 Uhr, dazwischen hat der Zähler 4 kWh gezählt. Dann bucht SourceAnalytix 2 kWh auf gestern und 2 kWh auf heute.</p><p>Für Leistungsquellen (W) gilt das nicht. Ihre Energie bis Mitternacht bucht SourceAnalytix ab v0.6.2 beim Wechsel selbst dem alten Tag zu, aber nur, wenn die Instanz um Mitternacht lief (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1254" target="_blank" rel="noreferrer">#1254</a>).</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Der Wechsel richtet sich nach der Uhrzeit des Rechners oder Containers, auf dem ioBroker läuft. Stimmt dort die Zeitzone nicht, wechselt SourceAnalytix zur falschen Stunde. Siehe <a href="./../fehlerbehebung/log-meldungen#midnight-crash-rollover-wrong-time">Absturz oder Wechsel zur falschen Zeit</a>.</p></div><p><strong>Siehe auch:</strong> <a href="./../referenz/states-und-meldungen#yesterday-last-week-last-month">Wo finde ich gestern, letzte Woche, letzten Monat?</a> · <a href="./../hintergrund/perioden-und-zeit#values-updated-live-midnight">Wann werden Werte aktualisiert?</a> · <a href="#data-back-up-move-new">Wo liegen die Daten, wie ziehe ich um?</a></p>`,93)])])}const g=n(r,[["render",s]]);export{p as __pageData,g as default};
